const a=(e,t,r)=>t>=e.minX&&t<=e.maxX&&r>=e.minZ&&r<=e.maxZ;export function regionOf(e,t,r){return t>=r.lawn.maxZ?"street":e>r.lawn.maxX?"neighbor":a(r.tarp,e,t)?"tarp":"lawn"}export function tally(e,t){const r={lawn:0,tarp:0,street:0,neighbor:0,total:e.count};for(let n=0;n<e.count;n++)r[regionOf(e.px[n],e.pz[n],t)]++;return r}export function clearedShare(e){return e.total>0?1-e.lawn/e.total:0}export function percent(e){return Math.max(0,Math.min(100,Math.floor(e*100+1e-9)))}export function formatCount(e){return String(Math.round(e)).replace(/\B(?=(\d{3})+(?!\d))/g,",")}export function leaves(e){return e===1?"1 leaf":`${formatCount(e)} leaves`}export function clockText(e){const t=Math.max(0,Math.ceil(e-1e-9));return`${Math.floor(t/60)}:${String(t%60).padStart(2,"0")}`}export function verdict(e){const t=clearedShare(e),r=o=>e.total>0?o/e.total:0;if(r(e.neighbor)>=.25)return{key:"neighbor",title:"The neighbors are talking",line:"A good share of your yard is now in theirs. They noticed."};let n;return t>=.9?n={key:"spotless",title:"Yard of the month",line:"The lawn is clear. Every neighbor on the street is a little jealous."}:t>=.7?n={key:"great",title:"Curb appeal restored",line:"The grass can see the sky again. Well done."}:t>=.45?n={key:"good",title:"Respectable work",line:"More lawn than leaves. That is a good afternoon."}:t>=.2?n={key:"start",title:"A solid start",line:"The leaves are on notice. Another round should finish the job."}:n={key:"leaves",title:"The leaves win this round",line:"They have the numbers. You have a leaf blower and another minute."},e.street>e.tarp*2&&r(e.street)>=.2&&(n={...n,line:`${n.line} Most of it went into the street, which the street did not ask for.`}),n}export function resultRows(e){return[{key:"tarp",label:"On the tarp",value:formatCount(e.tarp)},{key:"street",label:"In the street",value:formatCount(e.street)},{key:"neighbor",label:"Over the fence",value:formatCount(e.neighbor)},{key:"lawn",label:"Still on the lawn",value:formatCount(e.lawn)}]}export function shareText(e,t){const r=`I cleared ${percent(clearedShare(e))}% of my yard in ${t} seconds.`;let n="";return e.neighbor>0?n=` ${leaves(e.neighbor)} went to the neighbor.`:e.tarp>0&&(n=` ${leaves(e.tarp)} made it onto the tarp.`),`${r}${n} A leaf blower game on SceneXP.`}export function resultSentence(e){return`${verdict(e).title}. ${percent(clearedShare(e))} percent of the lawn cleared, with ${leaves(e.tarp)} on the tarp, ${leaves(e.street)} in the street, and ${leaves(e.neighbor)} over the fence.`}
